    "sanskritGujarati": "દેહોઽયં સાધનં મુક્તેર્ન ભોગમાત્રસાધનમ્।\nદુર્લભો નશ્વરશ્ચાઽયં વારંવારં ન લભ્યતે॥ ૨॥",
    "sanskritIast": "deho'yaṁ sādhanaṁ mukterna bhogamātrasādhanam|\ndurlabho naśvaraścā'yaṁ vāraṁvāraṁ na labhyate|| 2||",
