    "sanskritGujarati": "નાશાય સર્વદોષાણાં બ્રહ્મસ્થિતેરવાપ્તયે।\nકર્તું ભગવતો ભક્તિમ્ અસ્ય દેહસ્ય લમ્ભનમ્॥ ૪॥",
    "sanskritIast": "nāśāya sarvadoṣāṇāṁ brahmasthiteravāptaye|\nkartuṁ bhagavato bhaktim asya dehasya lambhanam|| 4||",
