    "sanskritGujarati": "વિજ્ઞાતવ્યમિદં સત્યં સત્સઙ્ગસ્ય હિ લક્ષણમ્।\nકુર્વન્નેવંવિધં દિવ્યં સત્સઙ્ગં સ્યાત્ સુખી જનઃ॥ ૯॥",
    "sanskritIast": "vijñātavyamidaṁ satyaṁ satsaṅgasya hi lakṣaṇam|\nkurvannevaṁvidhaṁ divyaṁ satsaṅgaṁ syāt sukhī janaḥ|| 9||",
    "meaningGu": "આવો દિવ્ય સત્સંગ કરનાર મનુષ્ય સુખી થાય છે. (૯)",
    "meaningHi": "सत्संग का यह सच्चा लक्षण समझना चाहिए। इस प्रकार का दिव्य सत्संग करने वाला मनुष्य सुखी होता है। (९)",
    "meaningEn": "This should be known as the authentic characteristic of Satsang. A person practicing such divine Satsang attains true happiness. (9)",
