    "sanskritDevanagari": "जात्या नैव महान् कोऽपि नैव न्यूनस्तथा यतः।\nजात्या क्लेशो न कर्तव्यः सुखं सत्सङ्गमाचरेत्॥ १६॥",
    "sanskritGujarati": "જાત્યા નૈવ મહાન્ કોઽપિ નૈવ ન્યૂનસ્તથા યતઃ।\nજાત્યા ક્લેશો ન કર્તવ્યઃ સુખં સત્સઙ્ગમાચરેત્॥ ૧૬॥",
    "sanskritIast": "jātyā naiva mahān ko'pi naiva nyūnastathā yataḥ|\njātyā kleśo na kartavyaḥ sukhaṁ satsaṅgamācaret|| 16||",
    "meaningGu": "જાતિએ કરીને કોઈ મહાન નથી અને કોઈ ન્યૂન પણ નથી. તેથી નાત-જાતને લઈને ક્લેશ ન કરવો ને સુખે સત્સંગ કરવો. (૧૬)",
    "meaningHi": "जन्म से न कोई महान है और न कोई हीन। इसलिए जाति के नाम पर क्लेश न करें और आनंदपूर्वक सत्संग का आचरण करें। (१६)",
    "meaningEn": "No one is superior or inferior by birth. Therefore, one should never harbor friction over caste and should joyfully practice Satsang. (16)",
