    "keyTeaching": "આ શ્લોકનો સમગ્ર અર્થ વચનામૃત ગઢડા પ્રથમ ૩૩ (Gadhada I-33) અને સ્વામીની વાત ૧/૧૬૮ (Swami ni Vato 1/168) ના સિદ્ધાંતોનું શબ્દશઃ સાક્ષાત્ પ્રતિપાદન કરે છે."
