    "anwayarthGu": "અન્વયાર્થ: મુમુક્ષુ પોતાના આત્માની મુક્તિ માટે સહજાનંદ શ્રીહરિ તથા અક્ષરબ્રહ્મ સ્વરૂપ ગુણાતીત ગુરુનો પ્રીતિએ કરીને આશરો કરે. (૨૦)",
    "anwayarthHi": "अन्वयार्थ: मुमुक्षु अपनी आत्मा की मुक्ति के लिए सहजानंद श्रीहरि तथा अक्षरब्रह्म स्वरूप गुणातीत गुरु का प्रीतिपूर्वक आश्रय ग्रहण करे। (२०)",
    "anwayarthEn": "Syntactic & Literal Meaning: For the liberation of one's atma, a spiritual seeker should lovingly take refuge in Sahajanand Shri Hari and the Aksharbrahma Gunatit Guru. (20)",
